// src/components/CartMain/CartMain.js
import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { addToCart } from '../../actions/cartActions'; // правильний шлях до action creators
import CartItem from '../CartItem/CartItem';
import CartSummary from '../CartSummary/CartSummary';
import './CartMain.css';

const Cart = () => {
  const dispatch = useDispatch();
  const cart = useSelector(state => state.cart);

  const handleAddToCart = (bookWithDetails) => {
    dispatch(addToCart(bookWithDetails));
  };

  return (
    <div className="cart-page">
      <h1>Ваш кошик</h1>
      <div className="cart-items-list">
        {cart.length > 0 ? (
          cart.map((item, index) => (
            <CartItem key={item.id || index} item={item} />
          ))
        ) : (
          <p className="cart-empty-message">Кошик порожній</p>
        )}
      </div>
      <CartSummary cart={cart} />
    </div>
  );
};

export default Cart;
